import{_ as t,o,c as s,ag as a}from"./chunks/framework.DXGyWiRo.js";const g=JSON.parse('{"title":"Export to ApiPost","description":"","frontmatter":{},"headers":[],"relativePath":"guide/export-apipost.md","filePath":"guide/export-apipost.md","lastUpdated":1789862141000}'),r={name:"guide/export-apipost.md"};function i(n,e,d,p,h,l){return o(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="export-to-apipost" tabindex="-1">Export to ApiPost <a class="header-anchor" href="#export-to-apipost" aria-label="Permalink to &quot;Export to ApiPost&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">Beta feature</p><p>The ApiPost channel is disabled by default. Enable it in the <strong>Features</strong> tab before using it.</p></div><p>EasyYapi exports HTTP endpoints to an <a href="https://www.apipost.cn/" target="_blank" rel="noreferrer">ApiPost</a> project. Endpoints are pushed through ApiPost&#39;s open API when a token and a project are configured; otherwise an <code>apipost.json</code> import file is written so you can import it by hand.</p><h2 id="enable-the-channel" tabindex="-1">Enable the channel <a class="header-anchor" href="#enable-the-channel" aria-label="Permalink to &quot;Enable the channel&quot;">​</a></h2><p>Open <kbd>Settings</kbd> &gt; <kbd>Other Settings</kbd> &gt; <kbd>EasyApi</kbd> &gt; <kbd>Features</kbd>. Under <strong>Export Channels</strong>, enable <strong>ApiPost (Beta)</strong>, then reopen Settings to reach the ApiPost tab — the same chicken-and-egg path as the other beta channels.</p><h2 id="configure-the-target" tabindex="-1">Configure the target <a class="header-anchor" href="#configure-the-target" aria-label="Permalink to &quot;Configure the target&quot;">​</a></h2><p>Open <kbd>Settings</kbd> &gt; <kbd>Other Settings</kbd> &gt; <kbd>EasyApi</kbd> &gt; <kbd>ApiPost (Beta)</kbd>:</p><table tabindex="0"><thead><tr><th>Field</th><th>Scope</th><th>Description</th></tr></thead><tbody><tr><td><strong>Server</strong></td><td>Application</td><td>Where ApiPost lives. Defaults to <code>https://open.apipost.net</code>. Only ever used to assemble <code>/open/apis/*</code> request URLs — never written into your document.</td></tr><tr><td><strong>Token</strong></td><td>Application</td><td>The ApiPost open API token, sent as the <code>api-token</code> header.</td></tr><tr><td><strong>Team</strong></td><td>—</td><td>Pick <strong>Load</strong> to fetch the teams the token can reach, then choose one.</td></tr><tr><td><strong>Project</strong></td><td>Project</td><td>Pick <strong>Refresh</strong> to list the projects of the selected team and choose the target.</td></tr></tbody></table><p>The token and server are stored once for the whole IDE; the project id is stored per repository, so switching repositories switches target projects instead of silently reusing the last one.</p><p>A project can only be picked, never typed: project ids are unreadable strings and a hand-typed one fails silently. An id that is already configured but not among the fetched rows is still kept as its own entry, so a repository pointing at a project outside the loaded team keeps working.</p><h2 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export&quot;">​</a></h2><ol><li>Open a file containing API endpoints, or select files/folders in the Project view.</li><li>Choose <strong>EasyYapi</strong> &gt; <strong>Export</strong> &gt; <strong>ApiPost (Beta)</strong>, or use the ApiPost action from the API Explorer.</li><li>Optionally pick a target project in the export dialog — otherwise the configured one is used.</li></ol><p>The channel is HTTP-only. gRPC endpoints are skipped, because ApiPost has no representation for them. If the selection contains no HTTP endpoints, the export reports that there is nothing to export.</p><h3 id="push-vs-file" tabindex="-1">Push vs. file <a class="header-anchor" href="#push-vs-file" aria-label="Permalink to &quot;Push vs. file&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Situation</th><th>Result</th></tr></thead><tbody><tr><td>Token <strong>and</strong> project id configured</td><td>The project is updated in place; the result is reported as created/updated endpoint counts.</td></tr><tr><td>Either one missing</td><td>An <code>apipost.json</code> file is written. Import it in ApiPost (<strong>导入</strong> → 选择「ApiPost 格式」→ 上传该文件).</td></tr></tbody></table><h2 id="two-urls-deliberately-separate" tabindex="-1">Two URLs, deliberately separate <a class="header-anchor" href="#two-urls-deliberately-separate" aria-label="Permalink to &quot;Two URLs, deliberately separate&quot;">​</a></h2><p>ApiPost export resolves two unrelated URLs and never derives one from the other:</p><table tabindex="0"><thead><tr><th>Rule</th><th>Meaning</th></tr></thead><tbody><tr><td><code>apipost.host</code></td><td>Where ApiPost lives. Only assembles open API requests. Defaults to the Server field.</td></tr><tr><td><code>apipost.server.url</code></td><td>The base URL of the API you are documenting. Written into the imported document&#39;s host/pre-URL (ApiPost&#39;s 前置 URL), so imported endpoints point at your service.</td></tr></tbody></table><p>Conflating them would point every imported endpoint at ApiPost itself. <code>apipost.server.url</code> is left empty when unset.</p><h2 id="apipost-rules" tabindex="-1">ApiPost rules <a class="header-anchor" href="#apipost-rules" aria-label="Permalink to &quot;ApiPost rules&quot;">​</a></h2><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Target project for this export</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">apipost.project</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=1234567890abcdef</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Base URL written into the imported document</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">apipost.server.url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=https://api.example.com</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Open API host override (rarely needed)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">apipost.host</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=https://open.apipost.net</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Rule</th><th>Description</th></tr></thead><tbody><tr><td><code>apipost.project</code></td><td>Target project id; overrides the configured project for this export</td></tr><tr><td><code>apipost.host</code></td><td>ApiPost open API base URL override</td></tr><tr><td><code>apipost.server.url</code></td><td>Base URL of the documented API, written to the document&#39;s host/base_path</td></tr><tr><td><code>apipost.export.before</code></td><td>Event that fires once before the export starts</td></tr><tr><td><code>apipost.save.before</code></td><td>Event that fires before an endpoint is pushed; the <code>document</code> binding can be mutated</td></tr><tr><td><code>apipost.save.after</code></td><td>Event that fires after an endpoint is pushed; <code>content</code> and <code>result</code> are exposed</td></tr></tbody></table><p>See <a href="/settings/config-rule">Config Rules</a> for rule syntax.</p><h2 id="re-export-behavior" tabindex="-1">Re-export behavior <a class="header-anchor" href="#re-export-behavior" aria-label="Permalink to &quot;Re-export behavior&quot;">​</a></h2><p>Re-exporting the same selection upserts rather than duplicates. Endpoints are matched against the project&#39;s existing nodes by <strong>method + path</strong>, and ApiPost&#39;s open API has no bulk import route, so the push is composed in dependency order:</p><ol><li><strong>Folders</strong> — reused by name when they already exist, because a child whose parent is missing is rejected.</li><li><strong>Models</strong> — deduplicated by name and pushed before the APIs that <code>$ref</code> them.</li><li><strong>APIs</strong> — created or updated in place.</li></ol><p>Server-regenerated folder and model ids are remapped into <code>parent_id</code> and <code>$ref</code> before each child is sent, since the server&#39;s own ids are the only trustworthy source.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="/guide/export-openapi">Export to OpenAPI</a> — a portable contract file instead of a project push</li><li><a href="/guide/export2yapi">Export to YApi</a> — push endpoints to a YApi project</li><li><a href="/settings/ide-setting">IDE Settings</a> — the ApiPost settings tab reference</li></ul>`,29)])])}const u=t(r,[["render",i]]);export{g as __pageData,u as default};
